coachView.loadJsFunction:
if(this.context.binding.get("value").get("selectedTransactions").length()>0){

	var tableRows = this.context.binding.get("value").get("selectedTransactions");
// In case the user saves (execution context is saved) while some fields are invalid,
// when reopening the screen, those fields must be marked as valid in order to correctly receive the Ajax service (refresh) result.

	for (var i = 0; i < tableRows.length; i++) {
   		 var row = tableRows.get(i);
   		 row.get("amountAllocatedForCurrencyRequest").setValid(true);
	}

	this.refreshTransactions();
	
}

if(this.context.binding.get("value").get("retrievedTransactions").length()>0){
	
	this.ui.get("reloadAmount").execute(JSON.stringify((this.context.binding.get("value").get("retrievedTransactions"))));
//	this.ui.get("retrievedTransactions1").setAllRecordsSelected(false);

}


if (this.context.options.isSearch.get("value") == true) {
	this.ui.get("Horizontal_Layout4").setVisible(true,true);
//	this.ui.get("Horizontal_Layout2").setVisible(false,true);
//	this.ui.get("retrievedTransactions1").setVisible(false,true);
	this.ui.get("Horizontal_Layout6").setVisible(false,true);
}else{
	this.ui.get("Horizontal_Layout4").setVisible(true,true);
//	this.ui.get("Horizontal_Layout2").setVisible(true,true);
//	this.ui.get("retrievedTransactions1").setVisible(true,true);
	this.ui.get("Horizontal_Layout6").setVisible(true,true);
}

inlineScript.scriptBlock:
this.insertUpdateTransaction = function (index, indexPath, remove) {
	this.context.binding.get("value").get("selectedTransactions").get(index).set("remove", remove);
	var previousAmountInCurrent = 0;
	var selected = this.context.binding.get("value").get("selectedTransactions").get(index);
	var referenceNo = selected.get("referenceNumber");
	var postingDate = selected.get("postingDate");
	var amountLinked = 0;

	var previousAmountInCurrent = this.context.binding.get("value").get("selectedTransactions").get(index).get("previousAmount");
	var currentRequestID = this.context.options.currentRequestID.get("value");
	if (!!this.context.binding.get("value").get("selectedTransactions").get(index).get("existAmount")) amountLinked = this.context.binding.get("value").get("selectedTransactions").get(index).get("existAmount") - previousAmountInCurrent;

	var amountInCurrent = this.context.binding.get("value").get("selectedTransactions").get(index).get("amountAllocatedForCurrencyRequest") ? this.context.binding.get("value").get("selectedTransactions").get(index).get("amountAllocatedForCurrencyRequest") : 0;
	var transactionAmount = this.context.binding.get("value").get("selectedTransactions").get(index).get("transactionAmount");

	if (!remove) {
		if (amountInCurrent <= transactionAmount - amountLinked && amountInCurrent >= 0) {
			this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/amountAllocatedForCurrentRequest[" + indexPath + "]").setValid(true);
			this.context.binding.get("value").get("selectedTransactions").get(index).set("requestID", currentRequestID);
			// console.dir("<<Transactions - Insert1>> ", this.context.binding.get("value").get("selectedTransactions").items);
			this.calculateCurrentInCurrecny(index);
			//			selected = this.context.binding.get("value").get("selectedTransactions").get(index);
			// console.log("!remove");
			// console.log("selected: ", selected);
			// console.dir("<<Transactions - Insert2>> ", this.context.binding.get("value").get("selectedTransactions").items);
			this.ui.get("insertUpdateTransactions").execute(JSON.stringify(selected));

			//reset
			//	this.context.options.previousTransaction.get("value").get(index)?.set("amountAllocatedForCurrencyRequest",0);
		} else {
			// console.log("Transactions - ELSE");
			this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/amountAllocatedForCurrentRequest[" + indexPath + "]").setData(0);
			if (amountInCurrent < 0 || !amountInCurrent) {
				// this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/amountAllocatedForCurrentRequest[" + indexPath + "]").setValid(false, "Amount entered ( " + amountInCurrent + " ) must be > 0");
			} else {
				this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/amountAllocatedForCurrentRequest[" + indexPath + "]").setValid(false, "Amount entered ( " + amountInCurrent + " ) plus Amount linked in bpm must not exceed transaction amount");
			}
		}
	} else {
		// console.log("remove transaction");
		this.ui.get("insertUpdateTransactions").execute(JSON.stringify(selected));
		//		this.context.binding.get("value").get("selectedTransactions").remove(index)
		this.ui.get("selectedTransactions1").removeRecord(index);
		//		this.ui.get("selectedTransactions1").refresh();
		this.calculateTotal();
		this.CollectioncurrencyVIS();
	}
	// this.ui.get("selectedTransactions1").refresh();
	// console.dir("<<Transactions - Insert3>> ", this.context.binding.get("value").get("selectedTransactions").items);
};

this.refreshTransactions = function () {
	var selectedList = [];
	selectedList = this.context.binding.get("value").get("selectedTransactions");
	//	console.log("<<refreshTransactions - JSON>>");
	//	console.log(JSON.stringify(selectedList));

	// console.dir("<<Transactions - Refresh>> ", selectedList.items);
	// console.log(selectedList.items);
	this.ui.get("refreshTransactions").execute(JSON.stringify(selectedList));
};

this.setCollectionCurrency = function () {
	var requestCurrency = this.context.options.requestCurrency.get("value");
	this.context.binding.get("value").set("currency", requestCurrency);
};
this.negotiatedVIS = function (me) {
	var reqCcy = this.context.options.requestCurrency.get("value").name;
	var colCcy = this.context.binding.get("value").get("currency").name;
	if (reqCcy == colCcy) {
		this.context.options.negotiatedExchangeRateVIS.set("value", "READONLY");
	} else {
		if (this.context.options.activityType.get("value") == "write") {
			this.context.options.negotiatedExchangeRateVIS.set("value", "DEFAULT");
		}
		if (this.context.options.activityType.get("value") != "write") {
			this.context.options.negotiatedExchangeRateVIS.set("value", "READONLY");
		}
	}
};

this.CollectioncurrencyVIS = function () {
	var isSearch = this.context.options.isSearch?.get("value");
	if(isSearch == true){
		this.ui.get("Single_Select1").setEnabled(false);
		return;
	} 
	if (this.context.binding.get("value").get("selectedTransactions").length() > 0) {
		this.ui.get("Single_Select1").setEnabled(false);
	} else {
		this.ui.get("Single_Select1").setEnabled(true);
	}
};

this.showRetrieveTransactionBtn = function () {
	if (this.context.options.activityType.get("value") == "write") {
		//this.ui.get("refreshTrans").setVisible(true,true);
		try {
			if (this.context.binding.get("value").get("currency").get("name") == null || this.context.binding.get("value").get("fromDate") == null || this.context.binding.get("value").get("ToDate") == null || this.context.binding.get("value").get("accountNo").get("value") == "" || this.context.binding.get("value").get("accountNo").get("value") == undefined) {
				this.ui.get("Button1").setVisible(false, true);
			} else {
				this.ui.get("Button1").setVisible(true, true);
			}
		} catch (err) {
			this.ui.get("Button1").setVisible(false, true);
		}
	} else {
		this.ui.get("Button1").setVisible(false, true);
		//			this.ui.get("refreshTrans").setVisible(false,true);
	}
};

//change the pagination direction for tables (on load of transactions table)
this.paginationDir = function () {
	var collection = document.getElementsByClassName("DT-pagination");
	for (var i = 0; i < collection.length; i++) {
		collection[i].style.position = "absolute";
	}
};

//this.context.binding.get("value").get("selectedTransactions").get(0).get("amountAllocatedForCurrencyRequest")

this.enableRefreshBtn = function () {
	var selectedTransLen = this.context.binding.get("value").get("selectedTransactions").length();
	if (selectedTransLen > 0) return true;
	else return false;
};

