this.manageAmounBtntVis = function (btn, index) {
	if (btn == "edit") {
		this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/edit[" + index + "]").setVisible(false, true);
		this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/submit[" + index + "]").setVisible(true);
		this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/amountAllocatedForCurrentRequest[" + index + "]").setEnabled(true);
		//this.ui.get("/DC_Templete1/"+this.context.viewid+"/selectedTransactions1/delete["+index+"]").setEnabled(false);
		this.ui.get("/DC_Templete1/" + this.context.viewid + "/Button2").setEnabled(false);
		/*		for(var i = 0 ; i<this.context.binding.get("value").get("selectedTransactions").length();i++){
			//due to pagination, won't work properly
			this.ui.get("/DC_Templete1/"+this.context.viewid+"/selectedTransactions1/delete["+i+"]").setEnabled(false);
					console.log(i+"-----------");
		}*/
		this.context.options.enableDelete.set("value", "READ ONLY");
	} else {
		if (this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/amountAllocatedForCurrentRequest[" + index + "]").isValid()) {
			this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/submit[" + index + "]").setVisible(false, true);
			this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/edit[" + index + "]").setVisible(true);
			this.ui.get("/DC_Templete1/" + this.context.viewid + "/selectedTransactions1/amountAllocatedForCurrentRequest[" + index + "]").setEnabled(false);
			//this.ui.get("/DC_Templete1/"+this.context.viewid+"/selectedTransactions1/delete["+i+"]").setEnabled(true);
			this.ui.get("/DC_Templete1/" + this.context.viewid + "/Button2").setEnabled(true);
			this.context.options.enableDelete.set("value", "DEFAULT");
		}
	}
};

this.calculateCurrentInCurrecny = function (index) {
	var convertedAmount = this.context.binding.get("value").get("selectedTransactions").get(index).get("amountAllocatedForCurrencyRequest") * this.context.binding.get("value").get("negotiatedExchangeRate");
	this.context.binding.get("value").get("selectedTransactions").get(index).set("allocatedAmountInRequestCurrency", convertedAmount);
	this.calculateTotal();
};
this.calculateTotal = function () {
	var sum = 0;
	var len = this.context.binding.get("value").get("selectedTransactions").length();

	for (var i = 0; i < len; i++) {
		sum += this.context.binding.get("value").get("selectedTransactions").get(i).get("allocatedAmountInRequestCurrency");
	}
	this.context.binding.get("value").set("totalAllocatedAmount", sum);
};

this.setRefreshedAmount = function (refreshedResult) {
	var parsedData = [];
	// console.log("setRefreshedAmount called with refreshedResult:");
	// console.log(refreshedResult);
	parsedData = JSON.parse(refreshedResult);

	if (!!parsedData) {
		var selectedList = this.context.binding.get("value").get("selectedTransactions");

		for (var i = 0; i < selectedList.length(); i++) {
			var selected = selectedList.get(i);
			var refNo = selected.get("referenceNumber");
			var postingDate = new Date(selected.get("postingDate"));

			for (var j = 0; j < parsedData.length; j++) {
				var parsed = parsedData[j];

				// Match both referenceNumber and postingDate (day/month/year)
				var transactionDate = new Date(parsed.postingDate);

				if (refNo === parsed.referenceNumber && postingDate.getDate() === transactionDate.getDate() && postingDate.getMonth() === transactionDate.getMonth() && postingDate.getFullYear() === transactionDate.getFullYear()) {
					// Set refreshed values
					selected.set("existAmount", parsed.existAmount);
					selected.set("amountAllocatedForCurrencyRequest", parsed.amountAllocatedForCurrencyRequest || 0);
					selected.set("allocatedAmountInRequestCurrency", parsed.allocatedAmountInRequestCurrency || 0);

					break;
				}
			}
		}

		if (this.context.binding.get("value").get("retrievedTransactions").length() > 0) {
			this.ui.get("reloadAmount").execute(JSON.stringify(this.context.binding.get("value").get("retrievedTransactions")));
		}
	}
};
this.setRate = function (collectionCurrency, requestCurrency) {
	var viewId = this.context.viewid - 1;
	if (!requestCurrency) requestCurrency = this.ui.get("/DC_Templete1/" + viewId + "/currency").getData().name;

	if (!!collectionCurrency && !!requestCurrency) {
		if (requestCurrency == collectionCurrency) this.ui.get("negotiatedExchangeRate").setEnabled(false);
		else this.ui.get("negotiatedExchangeRate").setEnabled(true);

		this.ui.get("getRate").execute(collectionCurrency + "-" + requestCurrency);
	}
};

this.setRatesResult = function () {
	var rate = this.context.options.rate.get("value");
	this.context.binding.get("value").set("standardExchangeRate", rate);
	this.context.binding.get("value").set("negotiatedExchangeRate", rate);
};

this.updateRetreiveTransaction = function (refNo, postingDate, updatedValue) {
	//update retreive transactions table with latest amount linked in bpm when changing the amount
	for (var j = 0; j < this.context.binding.get("value").get("retrievedTransactions").length(); j++) {
		var retrieved = this.context.binding.get("value").get("retrievedTransactions").get(j);
		var retrievedDate = new Date(retrieved.get("postingDate"));
		if (refNo == retrieved.get("referenceNumber") && postingDate.getDate() == retrievedDate.getDate() && postingDate.getMonth() == retrievedDate.getMonth() && postingDate.getFullYear() == retrievedDate.getFullYear()) {
			this.context.binding.get("value").get("retrievedTransactions").get(j).set("existAmount", updatedValue);
			break;
		}
	}
};

this.setReloadedAmount = function (result) {
	// set updated amount linked in bpm in retrieved transaction table when refreshing or reopening the screen after a while
	var parsedData = [];
	parsedData = JSON.parse(result);
	if (!!parsedData) {
		for (var i = 0; i < this.context.binding.get("value").get("retrievedTransactions").length(); i++) {
			var refNo = this.context.binding.get("value").get("retrievedTransactions").get(i).get("referenceNumber");
			var postingDate = new Date(this.context.binding.get("value").get("retrievedTransactions").get(i).get("postingDate"));
			for (var j = 0; j < parsedData.length; j++) {
				var transactionDate = new Date(parsedData[j].postingDate);

				if (refNo === parsedData[j].referenceNumber && postingDate.getDate() === transactionDate.getDate() && postingDate.getMonth() === transactionDate.getMonth() && postingDate.getFullYear() === transactionDate.getFullYear()) {
					this.context.binding.get("value").get("retrievedTransactions").get(i).set("existAmount", parsedData[j].existAmount);
					break;
				}
			}
		}
	}
};
