this.CheckFieldIsEnabled = function () {
	for (var i = 0; i < this.context.binding.get("value").get("selectedTransactions").length(); i++) {
		if (this.ui.get("selectedTransactions1").ui.getChild("Horizontal_Layout1", i).ui.getChild("amountAllocatedForCurrentRequest").isEnabled()) {
			this.ui.get("selectedTransactions1").ui.getChild("Horizontal_Layout1", i).ui.getChild("amountAllocatedForCurrentRequest").setValid(false, "Submission is required before saving.");
			return false;
		}
	}

	return true;
};
//++++++++++++++++++++++++++++++++++++++++++++++Error Handling+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
this.AjaxErrorHandling = function (errorMSG) {
	this.context.options.alertMessage.set("value", errorMSG);
	this.context.options.errorVis.set("value", "EDITABLE");
};
//===================================================================================================
// reusable function to prevent negative value on input (put it on input of the field)
this.preventNegativeInput = function (me) {
	// Add an event listener to the input field of the Integer control
	me.context.element.addEventListener("input", function (event) {
		// Get the current value of the input
		var currentValue = event.target.value;

		// If the value starts with a '-' prevent it
		if (currentValue.startsWith("-")) {
			event.target.value = currentValue.replace("-", "");
		}
	});
};
